      columns: [
        // 表格表头
        { title: "商品名称", slot: "goodsName" },
        { title: "价格", slot: "goodsPrice" },
        { title: "购买数量", key: "num" }
      ],
      goodsData: [],
      // 商品数据
      reasonList: [],
      // 售后原因列表
