      this.form = JSON.parse(JSON.stringify(this.content));
      if (this.form.licencePhoto) {
        this.form.legalPhoto = this.content.legalPhoto.split(",");
        this.form.licencePhoto = this.content.licencePhoto.split(",");
      }
